// Uppercase mappings generated by tools/generate_unicode_uppercase.rs.
// Unicode (18, 0, 0). 25-byte rows: source, length, three scalars or range (upper, end, step).
const UPPERCASE_ROWS: usize = 313usize;
const UPPERCASE_DATA: &str = "";

fn scalar(at: usize) -> u32 {
    let mut value = 0u32;
    let mut i = 0usize;
    while i < 6usize {
        let b = super::string::str_byte(UPPERCASE_DATA, at + i);
        let digit = if b <= 57u8 { b - 48u8 } else { b - 87u8 };
        value = value * 16u32 + digit as u32;
        i += 1usize;
    }
    value
}

pub fn push_uppercase(out: &mut super::string::String, c: char) {
    let key = c as u32;
    let mut low = 0usize;
    let mut high = UPPERCASE_ROWS;
    while low < high {
        let mid = low + (high - low) / 2usize;
        if scalar(mid * 25usize) <= key {
            low = mid + 1usize;
        } else {
            high = mid;
        }
    }
    if low != 0usize {
        let base = (low - 1usize) * 25usize;
        let start = scalar(base);
        let count = (super::string::str_byte(UPPERCASE_DATA, base + 6usize) - 48u8) as usize;
        if count == 0usize {
            let end = scalar(base + 13usize);
            let step = scalar(base + 19usize);
            if key <= end && (key - start) % step == 0u32 {
                out.push(super::string::unsafe_char(scalar(base + 7usize) + key - start));
                return;
            }
        } else if key == start {
            let mut i = 0usize;
            while i < count {
                out.push(super::string::unsafe_char(scalar(base + 7usize + i * 6usize)));
                i += 1usize;
            }
            return;
        }
    }
    out.push(c);
}
